type Route = "retrieve" | "parametric";
function route(query: string): Route {
  const needsFacts = /\b(our|policy|refund|price|current|latest|as of|version)\b/i.test(query);
  return needsFacts ? "retrieve" : "parametric";
}
// "what is our refund window?" -> retrieve (private + changeable)
// "reverse a string in JS"     -> parametric (general knowledge)

