// Clean raw text once, at ingestion, before chunk/embed.
const BOILERPLATE = [/^skip to/i, /^cookie/i, /^\u00a9/, /^\s*page \d+\s*$/i];
function clean(raw: string): string[] {
  return raw
    .split("\n")
    .map(line => line.replace(/\s+/g, " ").trim())   // collapse whitespace
    .filter(line => line.length > 0)                   // drop blanks
    .filter(line => !BOILERPLATE.some(rx => rx.test(line))); // drop chrome
}

