chunking-strategies.code:
// stride = size - overlap; chunks start at 0, stride, 2*stride, ...
function chunk(tokens: string[], size: number, overlap: number): string[][] {
  const stride = size - overlap;                 // advance per chunk
  const out: string[][] = [];
  for (let start = 0; start < tokens.length; start += stride) {
    out.push(tokens.slice(start, start + size)); // window [start, start+size)
    if (start + size >= tokens.length) break;    // last window covers the tail
  }
  return out;
}
// count formula: ceil((N - size) / stride) + 1  (for N > size)

