// An embedding = a vector. "Related" = "close in the vector space".
const dist = (a: number[], b: number[]) =>
  Math.sqrt(a.reduce((s, x, i) => s + (x - b[i]) ** 2, 0));
function nearest(query: number[], items: {id: string; vec: number[]}[]) {
  let best = items[0], bestD = Infinity;
  for (const it of items) {
    const d = dist(query, it.vec);
    if (d < bestD) { bestD = d; best = it; }   // closest = most related
  }
  return best.id;
}

