const versions = new Map<string, Map<string, unknown>>();  // version -> index
let ACTIVE = "v1";                    // reads go here
function buildInto(version: string, records: {id: string}[]) {
  const idx = versions.get(version) ?? new Map();
  for (const r of records) idx.set(r.id, r);   // populate in background
  versions.set(version, idx);
}
function activate(version: string) { ACTIVE = version; }  // atomic swap
function search(/* query */) { return versions.get(ACTIVE); }  // never the building one

