// Stage 1: fast, wide — top N by cosine (coarse order).
// Stage 2: rerank those N by a heavier query-doc relevance score, keep top k.
function rerankPipeline(candidates: {id: string; cosine: number}[],
                        relevance: (id: string) => number, k: number): string[] {
  return [...candidates]
    .sort((a, b) => b.cosine - a.cosine).slice(0, 50)   // stage 1: wide net
    .map(c => ({ id: c.id, rel: relevance(c.id) }))      // stage 2: rescore
    .sort((a, b) => b.rel - a.rel || a.id.localeCompare(b.id))
    .slice(0, k).map(x => x.id);                          // final precise top-k
}

