// Rewrite a pronoun/ellipsis follow-up into a standalone query using history.
function rewrite(query: string, lastTopic: string): string {
  // resolve common ellipsis/pronoun follow-ups to the prior topic
  if (/^(and )?(what about|how about) (theirs|it|that)\??$/i.test(query.trim()))
    return `${lastTopic} (comparison)`;
  if (/\b(the )?(annual|monthly) one\b/i.test(query))
    return query.replace(/(the )?(annual|monthly) one/i, "$2 " + lastTopic);
  return query;   // already self-contained
}
