type Chunk = { id: string; fact: string; value: string; updated: number };  // updated = epoch days
function fresh(chunks: Chunk[], now: number, ttlDays: number): Chunk[] {
  const alive = chunks.filter(c => now - c.updated <= ttlDays);   // expire old
  const byFact = new Map<string, Chunk>();
  for (const c of alive) {                                        // supersede conflicts
    const cur = byFact.get(c.fact);
    if (!cur || c.updated > cur.updated) byFact.set(c.fact, c);   // keep newest per fact
  }
  return [...byFact.values()];
}

