// recall@k = |relevant ∩ retrieved_topk| / |relevant|, averaged over queries.
function recallAtK(evalSet: {relevant: string[]; retrieved: string[]}[], k: number): number {
  const per = evalSet.map(q => {
    const topk = new Set(q.retrieved.slice(0, k));
    const hit = q.relevant.filter(id => topk.has(id)).length;
    return q.relevant.length ? hit / q.relevant.length : 0;
  });
  return per.reduce((a, b) => a + b, 0) / per.length;   // mean recall@k
}

