// RAGAS faithfulness = supported claims / total claims (0..1).
function faithfulness(claims: {text: string; terms: string[]}[], context: string): number {
  if (claims.length === 0) return 1;   // no claims -> nothing to contradict
  const ctx = context.toLowerCase();
  const supported = claims.filter(c => c.terms.every(t => ctx.includes(t.toLowerCase()))).length;
  return supported / claims.length;
}
// 1.0 = every claim supported; < 1.0 = at least one claim exceeds the evidence.

