// Latency: embed + search + rerank, then generation. Cost: context tokens are paid input.
function budget(k: number, tokensPerChunk: number, inputPer1k: number,
                latMs: {embed: number; search: number; rerank: number}): {ms: number; contextTokens: number; cost: number} {
  const contextTokens = k * tokensPerChunk;                 // injected on every call
  const cost = (contextTokens / 1000) * inputPer1k;         // paid as INPUT tokens
  const ms = latMs.embed + latMs.search + latMs.rerank;     // added before generation
  return { ms, contextTokens, cost };
}
// Raising k raises contextTokens linearly -> cost and prompt size scale with k.

