// Compose: rank -> top-k -> threshold gate -> ground+cite -> eval report.
const cosineRank = (cands) => [...cands].sort((a, b) => b.score - a.score || a.id.localeCompare(b.id));
function pipeline(cands, TAU, k) {
  const topk = cosineRank(cands).slice(0, k);
  if ((topk[0]?.score ?? 0) < TAU) return { action: "refuse" };   // unsupported -> honest no
  return { action: "answer", cited: topk.filter(c => c.score >= TAU) };
}
// recall@k and faithfulness are computed over the run for the report.

